async function readOnlyReconcileTest(){const env=await setup();env.context.recoveryProposal={...env.operation,state:'unknown',approval_status:'consumed'};vm.runInContext("operationStatus={proposals:[recoveryProposal],jobs:[{id:recoveryProposal.operation_id,state:'unknown',steps:[]}]};renderOperationJobs()",env.context);const button=walk(env.ids['operations-job-list']).find(n=>n.tagName==='button'&&n.textContent==='בדוק מה כבר נשמר במטא');assert(button);assert(!env.calls.some(c=>c.url.endsWith('/reconcile')));await button.onclick();await tick();const sent=env.calls.filter(c=>c.url.endsWith('/reconcile'));assert.equal(sent.length,1);assert.deepEqual(JSON.parse(sent[0].options.body),{operation_id:env.operation.operation_id,digest:env.operation.digest});assert(!env.calls.some(c=>/\/(approve|execute)$/.test(c.url)));console.log('PASS: uncertain launch has explicit read-only reconciliation with original binding and no repeat execution.');}
